		/**
		 * Translate, but keep `fallback` when the key is missing.
		 *
		 * t() hands back the key itself on a miss — the only way to tell "this
		 * keycap has no label" from "the label happens to read like a key".
		 */
		function messageOr(key, fallback) {
			const value = t(key);
			return value === key ? fallback : value;
		}

		/** A binding is either a keycap id (`APPR`) or a raw action (`approval.allow`). */
		/** Short verb shown on the tooltip's second line (reference: `批准`). */
		function keycapActionShort(keycapId) {
			return messageOr(`keycap.${keycapId}`, KEYCAP_BY_ID[keycapId]?.original?.label ?? keycapId);
		}

		function keycapActionLabel(keycapId) {
			const command = KEYCAP_COMMAND[keycapId];
			if (command) {
				const desc = messageOr(`cmdDesc.${command}`, "");
				if (desc) return desc;
			}
			return messageOr(`keycap.${keycapId}`, KEYCAP_BY_ID[keycapId]?.action ?? keycapId);
		}

		function resolveBinding(bindings, slotKey) {
			const value = bindings?.[slotKey];
			if (!value) return "noop";
			if (KEYCAP_BY_ID[value]) {
				const override = controller?.overrides?.[value];
				return override || KEYCAP_BY_ID[value].action;
			}
			return value;
		}

		function keycapForSlot(bindings, slotKey) {
			const value = bindings?.[slotKey];
			if (value && KEYCAP_BY_ID[value]) return KEYCAP_BY_ID[value];
			return KEYCAP_BY_ID[DEFAULT_KEYCAPS[slotKey]] ?? KEYCAPS[0];
		}

		// ---------------------------------------------------------- controller
		// ------------------------------------------------------- action model
		// 一个动作就是一个字符串，前缀决定它的去向：
		//   command:<id>  DSH 命令（先查本地处理器，再交给命令注册表）
		//   text:<text>   把文本插入输入框
		//   url:<href>    用浏览器打开
		//   skill:<name>  在输入框里引用技能
		//   ptt           按住说话
		//   noop          不绑定
		// 无前缀 = 0.2.x 的私有动词（session.new / effort.up …），继续兼容。
		const ACTION_PREFIXES = new Set(["command", "text", "url", "skill"]);

		/** 原版命令 id → 本插件已经能真实执行的动词。 */
		const REFERENCE_COMMAND_MAP = {
			"approval.approve": "approval.allow",
			"approval.decline": "approval.reject",
			forkThread: "session.fork",
			newTask: "session.new",
			settings: "settings.open",
			"composer.increaseReasoningEffort": "effort.up",
			"composer.decreaseReasoningEffort": "effort.down",
		};

		/**
		 * Turn the reference `original` descriptor into an executable action string.
		 * This is why every one of the 39 keycaps now does something: the catalog
		 * shipped with the panel already encodes the reference default.
		 */
		function actionFromReference(original) {
			if (!original || typeof original !== "object") return "noop";
			if (original.type === "named") return "ptt";
			if (original.type === "composer-text") return `text:${original.text ?? ""}`;
			if (original.type === "external-url") return `url:${original.url ?? ""}`;
			if (original.type === "skill") return `skill:${original.name ?? ""}`;
			if (original.type === "custom-shortcut") return "noop";
			if (original.type === "command") {
				const mapped = REFERENCE_COMMAND_MAP[original.command];
				return mapped ?? `command:${original.command}`;
			}
			return "noop";
		}

		function parseAction(action) {
			const text = String(action ?? "");
			if (!text || text === "noop") return { type: "noop", value: "" };
			const at = text.indexOf(":");
			const prefix = at < 0 ? "" : text.slice(0, at);
			if (ACTION_PREFIXES.has(prefix)) return { type: prefix, value: text.slice(at + 1) };
			return { type: "verb", value: text, arg: at < 0 ? "" : text.slice(at + 1) };
		}

		/** 面板里给动作显示的名字。 */
		/**
		 * Human name for an action string.
		 *
		 * The catalog and the short-verb table hold message keys, not text, so this
		 * is the single place that turns one into the other.
		 */
		function actionLabel(action) {
			const parsed = parseAction(action);
			if (parsed.type === "noop") return t("summary.noop");
			if (parsed.type === "ptt") return t("summary.ptt");
			if (parsed.type === "text") return t("summary.insertText", { value: parsed.value });
			if (parsed.type === "url") return t("summary.url", { value: parsed.value });
			if (parsed.type === "skill") return t("summary.skill", { value: parsed.value });
			if (parsed.type === "command") {
				const catalog = ACTION_CATALOG.find((entry) => entry.id === action);
				return catalog ? t(catalog.label) : parsed.value;
			}
			return ACTION_LABELS[parsed.value] ? t(ACTION_LABELS[parsed.value]) : parsed.value;
		}

		/**
		 * 面板和宿主共用一个 document，所以「当前焦点」可能是我们自己的控件。
		 * 这些副作用只服务宿主的输入区，焦点在我们面板里时必须什么都不做。
		 */
		function hostElement(node) {
			if (!node || node.nodeType !== 1 || !node.isConnected) return null;
			if (node === document.body || node === document.documentElement) return null;
			if (typeof node.closest === "function" && node.closest(".cm-root")) return null;
			return node;
		}

		/** 键盘/滚动类副作用：合成一次真实事件，交给宿主当前的焦点元素。 */
		function synthesizeKey(key, code, modifiers = {}) {
			const target = hostElement(document.activeElement) ?? document;
			const init = { key, code, bubbles: true, cancelable: true, ...modifiers };
			const down = target.dispatchEvent(new KeyboardEvent("keydown", init));
			target.dispatchEvent(new KeyboardEvent("keyup", init));
			return down === false;
		}

		/**
		 * 原版用 `code: "ComposerNavigation"` 让输入区环形移动高亮。宿主未必认识
		 * 这个私有 code，所以先发私有事件，若无人 preventDefault 再发普通方向键。
		 */
		function synthesizeNavigation(key) {
			const handled = synthesizeKey(key, "ComposerNavigation");
			if (!handled) synthesizeKey(key, key);
			return handled;
		}

		/** 找到当前可滚动的容器（输入区自己滚，否则回落到最近的可滚祖先/窗口）。 */
		function scrollConversation(delta) {
			let node = hostElement(document.activeElement);
			while (node && node !== document.body) {
				const style = window.getComputedStyle(node);
				if (/(auto|scroll)/.test(style.overflowY) && node.scrollHeight > node.clientHeight + 8) {
					node.scrollBy({ top: delta, behavior: "smooth" });
					return true;
				}
				node = node.parentElement;
			}
			window.scrollBy({ top: delta, behavior: "smooth" });
			return false;
		}

		/** 把文本写进当前输入框（textarea / contenteditable），触发 React 的 onChange。 */
		function insertIntoComposer(text) {
			if (!text) return false;
			const active = hostElement(document.activeElement);
			const candidates = [];
			if (active && (active.tagName === "TEXTAREA" || active.isContentEditable)) candidates.push(active);
			candidates.push(
				...document.querySelectorAll('[contenteditable="true"], textarea'),
			);
			const target = candidates
				.map(hostElement)
				.find((node) => node && !node.disabled && !node.readOnly);
			if (!target) return false;
			target.focus();
			if (target.tagName === "TEXTAREA") {
				const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, "value")?.set;
				const next = `${target.value}${text}`;
				setter ? setter.call(target, next) : (target.value = next);
				target.dispatchEvent(new Event("input", { bubbles: true }));
			} else {
				document.execCommand("insertText", false, text);
			}
			return true;
		}

		/**
		 * 提交输入框：优先回车，宿主自己会处理发送。
		 */
		function submitComposer() {
			const target = hostElement(document.activeElement);
			if (target && (target.tagName === "TEXTAREA" || target.isContentEditable)) {
				return synthesizeKey("Enter", "Enter");
			}
			return false;
		}

				// ---- 官方听写按钮（DSH「语音输入」插件）------------------------------
		// 设备麦克风键要和"点一下输入框里的听写按钮"完全一样：展开动画、波形、
		// 权限提示、识别中、插入文字全是官方组件的状态机。我们能做的最忠实的
		// 做法就是替用户点那个按钮，而不是绕过 UI 直接调转写服务。
		// 官方 aria-label 的文案键：locale 服务缺席时（正常不会）用我们自己的字典兜底，
		// 文案与官方 voice-input 词条保持一致，才能找到那个按钮。
		const VOICE_UI_LABEL_KEYS = {
			start: "voiceUi.startLabel",
			stop: "voiceUi.stopLabel",
			cancel: "voiceUi.cancelLabel",
			discard: "voiceUi.discardLabel",
			retry: "voiceUi.retryLabel",
			setup: "voiceUi.setupLabel",
		};

		/** 官方 aria-label 的当前语言版本（voice-input 命名空间由官方插件注册）。 */
		function voiceUiLabel(kind) {
			try {
				if (localeService && typeof localeService.bind === "function") {
					const value = localeService.bind("voice-input")?.(kind);
					if (typeof value === "string" && value && value !== kind) return value;
				}
			} catch {
				/* fall back to the static labels */
			}
			return null;
		}

		/** 官方组件展开后渲染的采集态容器：<div data-voice-activity="<phase>">。 */
		function voiceUiActivity() {
			try {
				return typeof document === "undefined" ? null : document.querySelector("[data-voice-activity]");
			} catch {
				return null;
			}
		}

		/** 找官方按钮：当前语言的 aria-label 优先，再退回内置中英文文案。 */
		function findVoiceButton(kind) {
			if (typeof document === "undefined") return null;
			const key = VOICE_UI_LABEL_KEYS[kind];
			if (!key) return null;
			const fallback = t(key);
			const labels = [...new Set([voiceUiLabel(kind), fallback].filter((label) => label && !label.startsWith("voiceUi.")))];
			for (const label of labels) {
				const selector = `button[aria-label="${String(label).replace(/["\\]/g, "\\$&")}"]`;
				let found = null;
				try {
					found = document.querySelector(selector);
				} catch {
					found = null;
				}
				if (found) return found;
			}
			return null;
		}

		/** 官方采集态 → 我们的 voiceState（灯效与提示共用）。 */
		function voicePhaseState(phase) {
			if (phase === "recording") return "recording";
			if (phase === "requesting" || phase === "transcribing") return "processing";
			if (phase === "feedback") return "completed";
			return "idle";
		}

		/**
		 * Toast requests, fanned out to whichever panel instance is mounted.
		 *
		 * The reference implementation appended a `#cm-toast` node to
		 * `document.body` and mutated it from outside React. The Host's plugin
		 * rules forbid writing outside the component, so the notifier is now a
		 * plain dispatcher and `ToastHost` owns the DOM inside the slot.
		 */
		const toastListeners = new Set();
		let toastSeq = 0;
		function toast(message, tone = "info") {
			toastSeq += 1;
			const item = { id: toastSeq, message, tone };
			for (const listen of toastListeners) {
				try {
					listen(item);
				} catch {
					/* one broken panel must not silence the others */
				}
			}
		}

		/** Renders the requests `toast()` dispatches; never touches document.body. */
		function ToastHost() {
			const [items, setItems] = React.useState([]);
			React.useEffect(() => {
				const timers = new Set();
				const listen = (item) => {
					setItems((prev) => [...prev.slice(-2), item]);
					const timer = setTimeout(() => {
						timers.delete(timer);
						setItems((prev) => prev.filter((entry) => entry.id !== item.id));
					}, 2600);
					timers.add(timer);
				};
				toastListeners.add(listen);
				return () => {
					toastListeners.delete(listen);
					for (const timer of timers) clearTimeout(timer);
				};
			}, []);
			if (items.length === 0) return null;
			return jsx("div", {
				className: "cm-toasts",
				children: items.map((entry) =>
					jsx("div", { className: "cm-toast", "data-tone": entry.tone, children: entry.message }, entry.id),
				),
			});
		}

		/** 面板偏好默认值；宿主 /state 里的 settings 会覆盖它。 */
		const DEFAULT_PREFS = {
			brightness: 100,
			autoOff: "3-minutes",
			encoderMode: "composer-navigation",
			agentSource: "recent",
			splitMic: false,
			singleTapAgentKeys: false,
			autoConnect: true,
		};

		const LONG_PRESS_MS = 500;

		class Controller {
			constructor(ctx) {
				this.ctx = ctx;
				this.bindings = { ...DEFAULT_BINDINGS };
				this.overrides = {};
				/** Six agent-key chat assignments (reference: customAgentAssignments). */
				this.agentSlots = Array.from({ length: 6 }, () => null);
				/** 用户自己勾选的那份映射；自动来源下与 agentSlots 分开存。 */
				this.customSlots = Array.from({ length: 6 }, () => null);
				/** 宿主报告的 subagent 会话 id：智能体键只认主对话（见 mainSessionEntries）。 */
				this.subagentIds = [];
				this.settings = { ...DEFAULT_PREFS };
				/** Skill catalog (`ctx.remote.skills.list`), used by the action pickers. */
				this.skills = [];
				this.skillsLoadedFor = null;
				this.stream = null;
				this.logs = [];
				this.lastStick = 0;
				this.pendingApproval = null;
				this.listeners = new Set();
				this.lightingTimer = null;
				this.lightingInterval = null;
				this.beaconInterval = null;
				/** 本窗口收到的 v.oai.hid 通知数（诊断用）。 */
				this.hidSeen = 0;
				this.lastHintKey = "";
				/** 选中态订阅的 disposer（拿不到 observable 时为 null）。 */
				this.selectionDispose = null;
				this.pressedKeys = new Set();
				this.disposed = false;
				/** 旋钮：500 ms 长按，短按释放算单击。 */
				this.knob = { pressedAt: 0, timer: null, longFired: false, lastPulseAt: 0, pulses: 0, pulseTimer: null, pendingTick: null };
				/** 智能体键：350 ms 内二次按下才算双击。 */
				this.agentTap = { slot: -1, at: 0, timer: null };
				/** 按住说话状态机（reference: idle/pressed/latched/suppressing）。 */
				this.ptt = { state: "idle", startedAt: 0, deadline: 0, timer: null, down: false };
				/** idle | recording | processing | completed —— 驱动语音灯效。 */
				this.voiceState = "idle";
				this.voiceDoneTimer = null;
				/** "ui" 表示这一段语音由官方听写按钮驱动（点击开始/停止）。 */
				this.voiceUi = null;
				this.voiceUiTimer = null;
				this.voiceLastPhase = "";
				/** 多窗口时只有 owner 执行硬件动作。 */
				this.ownerId = Math.random().toString(36).slice(2, 10);
				this.owner = false;
				this.ownerTimer = null;
				this.channel = null;
				/** Kept so stop() can detach it: a bare addEventListener has no handle. */
				this.ownerListener = null;
			}

			subscribe(listener) {
				this.listeners.add(listener);
				return () => this.listeners.delete(listener);
			}

			notify() {
				for (const listener of this.listeners) {
					try {
						listener();
					} catch {
						/* a listener must not break event dispatch */
					}
				}
			}

			log(line) {
				this.logs.push(`${new Date().toLocaleTimeString()}  ${line}`);
				if (this.logs.length > 60) this.logs.shift();
				this.notify();
			}

			start() {
				try {
					this.loadSkills();
				} catch {
					/* 技能列表是可选能力：它出错不该连硬件运行时一起停掉 */
				}
				this.claimOwnership();
				// 灯光不能只在面板打开时更新：宿主侧每 1.5 s 推一次六键模型。
				this.startLightingLoop();
				if (this.stream) return;
				try {
					this.stream = new EventSource(`${API}/events`);
					this.stream.onmessage = (message) => {
						let event;
						try {
							event = JSON.parse(message.data);
						} catch {
							return;
						}
						if (event.type === "notify") this.onNotify(event);
						else if (event.type === "state") {
							// 拔线/重连：清掉按下状态，避免 PTT 卡在录音、长按定时器悬空。
							this.resetInputState();
							this.notify();
						}
					};
				} catch {
					this.stream = null;
				}
			}

			stop() {
				this.disposed = true;
				if (this.stream) this.stream.close();
				this.stream = null;
				if (this.lightingTimer) clearTimeout(this.lightingTimer);
				if (this.lightingInterval) clearInterval(this.lightingInterval);
				if (this.beaconInterval) clearInterval(this.beaconInterval);
				this.beaconInterval = null;
				if (this.selectionDispose) {
					try {
						this.selectionDispose();
					} catch {
						/* already released */
					}
					this.selectionDispose = null;
				}
				if (this.knob.timer) clearTimeout(this.knob.timer);
				if (this.agentTap.timer) clearTimeout(this.agentTap.timer);
				if (this.voiceDoneTimer) clearTimeout(this.voiceDoneTimer);
				this.voiceDoneTimer = null;
				this.stopVoiceUiWatch();
				this.voiceState = "idle";
				this.voiceUi = null;
				if (this.ownerTimer) clearInterval(this.ownerTimer);
				// Everything claimOwnership() attached has to come off again:
				// the storage listener outlives the component otherwise, and a
				// closed BroadcastChannel still holds its port open.
				this.releaseOwnership();
				if (this.ownerListener) window.removeEventListener("storage", this.ownerListener);
				this.ownerListener = null;
				try {
					this.channel?.close();
				} catch {
					/* already closed */
				}
				this.channel = null;
			}

			/**
			 * 原版只让主窗口处理硬件输入，否则一次按键会在每个窗口各执行一遍。
			 * 这里用一个带 6 s 租约的 localStorage 主控标记做轻量选举。
			 */
			claimOwnership() {
				const key = "dsh-micro.owner";
				const write = () => {
					try {
						window.localStorage.setItem(key, JSON.stringify({ id: this.ownerId, at: Date.now() }));
					} catch {
						/* private mode: fall back to single-window behaviour */
					}
				};
				const evaluate = () => {
					let record = null;
					try {
						record = JSON.parse(window.localStorage.getItem(key) ?? "null");
					} catch {
						record = null;
					}
					const stale = !record || typeof record.at !== "number" || Date.now() - record.at > 6000;
					if (stale) {
						write();
						this.owner = true;
					} else if (record.id === this.ownerId) {
						write();
						this.owner = true;
					} else {
						this.owner = false;
					}
				};
				evaluate();
				this.ownerTimer = setInterval(evaluate, 2000);
				this.ownerTimer.unref?.();
				this.ownerListener = evaluate;
				window.addEventListener("storage", evaluate);
				try {
					this.channel = new BroadcastChannel("dsh-micro");
					this.channel.onmessage = (event) => {
						if (event.data?.type === "release" && event.data.id !== this.ownerId) evaluate();
					};
				} catch {
					this.channel = null;
				}
			}

			releaseOwnership() {
				try {
					if (this.owner) {
						const key = "dsh-micro.owner";
						const record = JSON.parse(window.localStorage.getItem(key) ?? "null");
						if (record?.id === this.ownerId) window.localStorage.removeItem(key);
					}
				} catch {
					/* ignore */
				}
				this.channel?.postMessage?.({ type: "release", id: this.ownerId });
			}

			/** 宿主 /state 里的 settings 落地到控制器。 */
			applySettings(settings) {
				if (!settings || typeof settings !== "object") return;
				const next = { ...this.settings, ...settings };
				if (JSON.stringify(next) === JSON.stringify(this.settings)) return;
				this.settings = next;
				this.notify();
			}

			resetInputState() {
				this.pressedKeys.clear();
				this.clearPttTimer();
				this.ptt = { state: "idle", startedAt: 0, deadline: 0, timer: null, down: false };
				if (this.knob.timer) clearTimeout(this.knob.timer);
				if (this.knob.pulseTimer) clearTimeout(this.knob.pulseTimer);
				if (this.knob.pendingTick) clearTimeout(this.knob.pendingTick);
				this.knob = { pressedAt: 0, timer: null, longFired: false, lastPulseAt: 0, pulses: 0, pulseTimer: null, pendingTick: null };
				if (this.agentTap.timer) clearTimeout(this.agentTap.timer);
				this.agentTap = { slot: -1, at: 0, timer: null };
			}

			onNotify(event) {
				if (event.method === "v.oai.hid") {
					this.hidSeen = (this.hidSeen ?? 0) + 1;
					this.onKey(event.params ?? {});
				}
				else if (event.method === "v.oai.rad") this.onStick(event.params ?? {});
			}

			onKey(params) {
				const key = String(params.k ?? "");
				const act = Number(params.act ?? -1);
				if (!key) return;
				// 宽麦克风键合并模式下 ACT11 是同一个物理键，必须丢弃，否则一次按压触发两次。
				if (!this.settings.splitMic && (key === "ACT11" || key === "ACT10_ACT11")) return;
				if (act === 0) this.pressedKeys.delete(key);
				else if (act === 1) this.pressedKeys.add(key);
				// 预览图的按下高亮要立刻反映到面板上。
				if (act === 0 || act === 1) this.notify();
				// 旋钮和智能体键要看到按下/松开两个边沿，放在这里分发。
				if (key.startsWith("ENC")) {
					this.onEncoder(key, act);
					return;
				}
				if (key.startsWith("AG")) {
					this.onAgentKey(key, act);
					return;
				}
				if (act === 0) {
					// 麦克风键的松手必须交给 PTT 状态机，否则短按闩锁永远收不到释放。
					if (this.resolveSlot(key) === "ptt") this.onPttRelease();
					return;
				}
				// 只有旋钮会发 repeat(2)；按键重复会让人以为按键卡住。
				if (act !== 1) return;
				const action = this.resolveSlot(key);
				if (action === "ptt") {
					this.onPttPress();
					return;
				}
				if (action === "noop") return;
				if (!this.owner) {
					this.log(t("log.ownerTaken", { "key": key }));
					return;
				}
				this.log(`${key} → ${actionLabel(action)}`);
				void this.dispatch(action, { key });
			}

			resolveSlot(slotKey) {
				return resolveBinding(this.bindings, slotKey);
			}

			// ---- 旋钮 -------------------------------------------------------
			onEncoder(key, act) {
				if (key === "ENC_CW" || key === "ENC_CC") {
					const direction = key === "ENC_CW" ? 1 : -1;
					// 旋转 tick 在固件里是 act=2（original-runtime.md §5）。act=1 只作
					// 兼容：先等 40 ms，同一格随后来了 act=2 就把这次按下丢掉，避免
					// 一格触发两次动作。
					if (act === 1) {
						if (this.knob.pendingTick) return;
						this.knob.pendingTick = setTimeout(() => {
							this.knob.pendingTick = null;
							this.knobPulse(direction);
						}, 40);
						this.knob.pendingTick.unref?.();
						return;
					}
					if (act !== 2) return;
					if (this.knob.pendingTick) {
						clearTimeout(this.knob.pendingTick);
						this.knob.pendingTick = null;
					}
					this.knobPulse(direction);
					return;
				}
				// 按下/释放走长按 + 单击状态机。
				if (act === 1) {
					this.knob.pressedAt = Date.now();
					this.knob.longFired = false;
					if (this.knob.timer) clearTimeout(this.knob.timer);
					this.knob.timer = setTimeout(() => {
						this.knob.timer = null;
						this.knob.longFired = true;
						this.onKnobLongPress();
					}, LONG_PRESS_MS);
					return;
				}
				if (act !== 0) return;
				if (this.knob.timer) {
					clearTimeout(this.knob.timer);
					this.knob.timer = null;
				}
				if (this.knob.longFired) {
					this.knob.longFired = false;
					return;
				}
				this.onKnobClick();
			}

			/**
			 * 一格旋转 = 一次动作。原版直接依赖固件每格一个 act=2 事件
			 * （original-runtime.md §5.1：「无需客户端累积」）；180 ms 只用于清掉
			 * 供 HUD/小游戏读的瞬态脉冲指示，不能吞格——旧实现在这里合并快转，
			 * 转 3 格只会走 1 步。
			 */
			knobPulse(direction) {
				const now = Date.now();
				this.knob.lastPulseAt = now;
				this.knob.pulses += 1;
				if (this.knob.pulseTimer) clearTimeout(this.knob.pulseTimer);
				this.knob.pulseTimer = setTimeout(() => {
					this.knob.pulseTimer = null;
					this.knob.pulses = 0;
				}, 180);
				this.knob.pulseTimer.unref?.();
				const mode = this.settings.encoderMode ?? "composer-navigation";
				if (mode === "reasoning") {
					// 原版：顺时针降低推理强度，逆时针提高。
					if (!this.owner) return;
					void this.dispatch(direction > 0 ? "effort.down" : "effort.up");
					return;
				}
				if (mode === "conversation-scroll") {
					scrollConversation(direction > 0 ? 160 : -160);
					return;
				}
				if (mode === "composer-navigation") {
					synthesizeNavigation(direction > 0 ? "ArrowDown" : "ArrowUp");
					return;
				}
				const action = this.resolveSlot(direction > 0 ? "ENC_CW" : "ENC_CC");
				if (action === "noop" || !this.owner) return;
				this.log(t("log.knobTurn", { "dir": direction > 0 ? t("log.knobRight") : t("log.knobLeft"), "action": actionLabel(action) }));
				void this.dispatch(action, { key: "ENC" });
			}

			onKnobClick() {
				const mode = this.settings.encoderMode ?? "composer-navigation";
				if (mode === "composer-navigation") {
					synthesizeKey("Enter", "Enter");
					return;
				}
				if (mode === "conversation-scroll") {
					window.scrollTo({ top: document.body.scrollHeight, behavior: "smooth" });
					return;
				}
				if (!this.owner) return;
				this.dispatch(this.resolveSlot("ENC"));
			}

			onKnobLongPress() {
				if (!this.owner) return;
				const mode = this.settings.encoderMode ?? "composer-navigation";
				if (mode === "custom") {
					const action = this.resolveSlot("ENC_LONG");
					if (action !== "noop") {
						this.dispatch(action, { key: "ENC" });
						return;
					}
				}
				// 非自定义模式：长按进入 DSH Micro 设置页（原版行为）。
				this.dispatch("settings.open");
			}

			// ---- 智能体键 ---------------------------------------------------
			/**
			 * 原版语义（original-settings.md §5.5 / original-runtime.md §3.5）：
			 *
			 * - 聊天绑定：**单击就打开/切换该聊天**（渲染端在 act===1 时直接 `Dz`
			 *   打开，双击判定发生在主进程、只管「把窗口提到前台」）；
			 * - 双击（350 ms 内同键再按）或 `singleTapAgentKeys` 打开时才额外抢焦点
			 *   ——页面只能 `window.focus()`，能不能真抢到前台由 OS 决定；
			 * - **窗口不在前台时单击就要提窗**：参考实现里主窗口不存在（或已被
			 *   关掉）时走 `openWindowForAgentTap()` → `showWindow(stealFocus)`，
			 *   所以用户体感是「按一下就聚焦」；浏览器里等价的信号是
			 *   `document.hasFocus()` 为假，此时单击也补一次 focus；
			 * - 动作绑定（键帽/命令/技能）按下即执行，没有单击/双击语义；
			 * - 空绑定：单击即新建会话并把该键绑上去（原版是 pending + 新建）。
			 */
			onAgentKey(key, act) {
				const slot = Number(key.slice(2));
				if (!Number.isInteger(slot) || slot < 0 || slot > 5) return;
				if (act !== 1) return;
				const bound = this.bindings[`AG0${slot}`];
				// 线程绑定只有两种：没绑定（空键）或显式的 `session.open[:N]` 引用。
				// 其它一切都是动作绑定——键帽 id（含空键帽 EMPT）、`command:`/`text:`/
				// `url:`/`skill:`/`ptt` 以及 0.2.x 私有动词。旧实现把「非键帽 id」一律
				// 当聊天槽，于是快捷键/技能分配永远不会执行（parity B4）。
				const isThreadSlot = !bound || /^session\.open(:\d+)?$/.test(String(bound));
				if (!isThreadSlot) {
					const action = resolveBinding(this.bindings, `AG0${slot}`);
					if (action !== "noop" && this.owner) void this.dispatch(action, { key });
					return;
				}
				const now = Date.now();
				const secondTap = this.agentTap.slot === slot && now - this.agentTap.at < 350;
				if (this.agentTap.timer) clearTimeout(this.agentTap.timer);
				if (secondTap) {
					this.agentTap = { slot: -1, at: 0, timer: null };
					// 第二次按下：不再重复打开同一个会话，只补一次「抢前台」。
					this.focusWindow();
					return;
				}
				this.agentTap = { slot, at: now, timer: null };
				this.agentTap.timer = setTimeout(() => {
					this.agentTap.timer = null;
					this.agentTap.slot = -1;
				}, 350);
				const assigned = Array.isArray(this.agentSlots) ? this.agentSlots[slot] : null;
				if (assigned === null) this.log(t("log.emptyAgentKey", { "slot": slot + 1 }));
				this.openAgentSlot(slot);
				// 参考实现里 `getPrimaryWindow()` 为空（窗口还没建/已被关掉）时，
				// 单击会走 `openWindowForAgentTap()` 并 `showWindow(stealFocus)`——
				// 用户体感就是「按一下就聚焦」。浏览器里「窗口不在前台」的唯一
				// 可观测信号是 `document.hasFocus()`，失焦时同样补一次 focus。
				if (this.settings.singleTapAgentKeys || !this.pageHasFocus()) this.focusWindow();
			}

			/**
			 * 页面是否持有前台焦点。`document.hasFocus()` 在 Electron 渲染进程里
			 * 随窗口失焦/最小化变为 false；取不到时按「有焦点」处理（不额外提窗）。
			 */
			pageHasFocus() {
				try {
					return typeof document === "undefined" || !document.hasFocus ? true : document.hasFocus();
				} catch {
					return true;
				}
			}

			/**
			 * 原版主进程用 `showWindow(stealFocus:true)` 把窗口提到前台。页面里只有
			 * `window.focus()` 这一种请求，是否生效由宿主/OS 决定，失败也不影响切换。
			 */
			focusWindow() {
				try {
					window.focus?.();
				} catch {
					/* a denied focus request is not an error */
				}
			}

			openAgentSlot(slot) {
				if (!this.owner) return;
				const ctx = this.ctx;
				const assigned = Array.isArray(this.agentSlots) ? this.agentSlots[slot] : null;
				if (assigned) {
					openSession(ctx, assigned);
					return;
				}
				const entries = mainSessionEntries(sessionsOf(ctx)?.list, this.subagentIds);
				const entry = entries[slot];
				if (entry) {
					openSession(ctx, entry.id);
					return;
				}
				// 没有任何会话可开：新建一个，然后把这个键绑定到它。
				const workspace = service(ctx, "uiWorkspace");
				const started = workspace?.startSession?.();
				Promise.resolve(started)
					.then((created) => {
						const id = typeof created === "string" ? created : created?.id ?? created?.sessionId;
						if (!id) return undefined;
						this.agentSlots[slot] = id;
						return post({ op: "agent-slot", slot, sessionId: id });
					})
					.catch(() => undefined);
			}

			// ---- 按住说话 ---------------------------------------------------
			/**
			 * PTT 状态机，逐行对应原版 `z`（original-runtime.md §6.2）；文案也是
			 * 「按住即可听写，轻点两下可持续录音」：
			 *
			 *   idle --press--> pressed + start
			 *   pressed --release(held>=350)--> idle + stop
			 *   pressed --release(held<350)--> waiting(deadline=pressedAt+350)
			 *   waiting --press--> latched（继续录音，不补 start/stop）
			 *   waiting --timeout--> idle + stop
			 *   latched --press--> suppressing(deadline=now+350) + stop
			 *   suppressing --press--> 吞掉（防连击误启）
			 *   suppressing --timeout--> 还按着 ? pressed + start : idle
			 *
			 * 旧实现是「短按松开即永久闩锁」，既没有 350 ms 等待窗口，也没有抑制态：
			 * 单击一次就一直录，双击反而被当成两次独立短按。
			 */
			onPttPress() {
				const now = Date.now();
				const state = this.ptt.state;
				this.ptt.down = true;
				// 抑制窗口内的按下直接吞掉，防止连击误启。
				if (state === "suppressing") return;
				this.clearPttTimer();
				if (state === "waiting") {
					// 350 ms 内的第二击：免手持持续录音。
					this.ptt.state = "latched";
					this.ptt.startedAt = now;
					this.log(t("log.recordingStarted"));
					return;
				}
				if (state === "latched") {
					// 免手持状态下再按：停止，并进入 350 ms 抑制窗口。
					this.ptt.state = "suppressing";
					this.ptt.startedAt = now;
					this.ptt.deadline = now + 350;
					this.voiceStop("tap");
					this.ptt.timer = setTimeout(() => this.onPttTimeout(), 350);
					return;
				}
				this.ptt.state = "pressed";
				this.ptt.startedAt = now;
				// 语音通道不可用时不要停在 pressed，否则松开还会走一遍停止逻辑。
				if (this.voiceStart() === false) {
					this.ptt.state = "idle";
					this.ptt.startedAt = 0;
				}
			}

			/** 松开：长按即停；短按先保留 350 ms 等第二击。 */
			onPttRelease() {
				this.ptt.down = false;
				if (this.ptt.state !== "pressed") return;
				const held = Date.now() - this.ptt.startedAt;
				this.clearPttTimer();
				if (held >= 350) {
					this.ptt.state = "idle";
					this.voiceStop("release");
					return;
				}
				this.ptt.state = "waiting";
				this.ptt.deadline = this.ptt.startedAt + 350;
				const delay = Math.max(0, this.ptt.deadline - Date.now());
				this.ptt.timer = setTimeout(() => this.onPttTimeout(), delay);
			}

			/** 状态机的超时分支（第二击窗口 / 抑制窗口）。 */
			onPttTimeout() {
				this.ptt.timer = null;
				const state = this.ptt.state;
				if (state === "waiting") {
					this.ptt.state = "idle";
					this.voiceStop("timeout");
					return;
				}
				if (state === "suppressing") {
					if (this.ptt.down) {
						// 抑制窗口过后仍按着：当作长按的新一段。
						this.ptt.state = "pressed";
						this.ptt.startedAt = Date.now();
						if (this.voiceStart() === false) {
							this.ptt.state = "idle";
							this.ptt.startedAt = 0;
						}
					} else {
						this.ptt.state = "idle";
					}
				}
			}

			clearPttTimer() {
				if (this.ptt.timer) clearTimeout(this.ptt.timer);
				this.ptt.timer = null;
			}

			/**
			 * 宿主语音服务：DSH「语音输入」插件挂载后才提供 `remote.speech`
			 * （transcribe / catalog / configure / prepare）。没开就是 undefined，
			 * 这正是"提醒用户去开启插件"的判定点。
			 */
			speechService() {
				return service(this.ctx, "remote.speech");
			}

			/** 语音提示：missing=插件没开；uiMissing=找不到听写按钮；busy=正在识别。 */
			voiceHint(kind) {
				if (kind === "missing") {
					this.voiceState = "idle";
					this.log(t("log.voicePluginMissing"));
					toast(t("toast.voicePluginMissing"), "warn");
				} else if (kind === "uiMissing") {
					this.voiceState = "idle";
					this.log(t("log.voiceUiMissing"));
					toast(t("toast.voiceUiMissing"), "warn");
				} else if (kind === "notReady") {
					this.voiceState = "idle";
					this.log(t("log.voiceNotReady"));
					toast(t("toast.voiceNotReady"), "warn");
				} else if (kind === "locked") {
					this.voiceState = "idle";
					this.log(t("log.voiceLocked"));
					toast(t("toast.voiceLocked"), "warn");
				} else if (kind === "busy") {
					this.log(t("log.voiceBusy"));
				}
				this.notify();
			}

			/** 转写成功/官方流程结束：亮一下完成态（原版 completed 是白色常亮），1.5 s 后回落。 */
			voiceDone() {
				this.voiceState = "completed";
				this.notify();
				if (this.voiceDoneTimer) clearTimeout(this.voiceDoneTimer);
				this.voiceDoneTimer = setTimeout(() => {
					this.voiceDoneTimer = null;
					this.voiceState = "idle";
					this.notify();
				}, 1500);
				this.voiceDoneTimer.unref?.();
			}

			/**
			 * 轮询官方采集态，把"录音中/识别中/完成"映射成设备灯效。
			 *
			 * mode="stop" 时官方可能很快就结束（转写完成/取消），没见过采集态时只等
			 * 一小段就按"已完成"收尾；mode="start" 时给权限弹窗留足时间。
			 */
			watchVoiceUi(mode = "start") {
				this.stopVoiceUiWatch();
				const startedAt = Date.now();
				const graceMs = mode === "stop" ? 120 : 800;
				const timer = setInterval(() => {
					const activity = voiceUiActivity();
					if (!activity) {
						// 只有见过采集态才算"官方流程结束"；刚点完按钮还没渲染出来时不能误判。
						if (this.voiceLastPhase) {
							this.stopVoiceUiWatch();
							this.voiceUi = null;
							if (this.voiceState !== "idle") this.voiceDone();
						} else if (Date.now() - startedAt > graceMs) {
							this.stopVoiceUiWatch();
							this.voiceUi = null;
							if (mode === "stop") {
								if (this.voiceState !== "idle") this.voiceDone();
							} else {
								this.voiceState = "idle";
								this.notify();
							}
						}
						return;
					}
					const phase = activity.getAttribute?.("data-voice-activity") ?? "";
					this.voiceLastPhase = phase;
					const next = voicePhaseState(phase);
					if (next !== this.voiceState) {
						this.voiceState = next;
						this.notify();
					}
				}, 150);
				timer.unref?.();
				this.voiceUiTimer = timer;
			}

			stopVoiceUiWatch() {
				if (this.voiceUiTimer) clearInterval(this.voiceUiTimer);
				this.voiceUiTimer = null;
				this.voiceLastPhase = "";
			}

			/**
			 * 按下麦克风键 / PTT：按官方听写当前所处的阶段决定动作（这就是"按一下按钮"
			 * 的等价操作）：
			 *   idle        → 点"开始录音"；
			 *   recording / requesting → 这次按下当"停止"；
			 *   transcribing → 正在识别，忽略（避免把识别打断）；
			 *   feedback    → 上一次停在提示行（未识别/失败/冲突）：直接点"重新录音"，
			 *                 一次按下就开始下一段，不需要用户再点一次关闭提示；
			 * 找不到按钮 → **不开始录音**，只提示（插件没开 / 输入区没在前台）。
			 */
			voiceStart() {
				const phase = voiceUiActivity()?.getAttribute?.("data-voice-activity") ?? "";
				if (phase === "recording" || phase === "requesting") {
					// 已经在采集（可能是用户自己点的按钮）：这次按下当停止。
					this.voiceUi = "ui";
					return true;
				}
				if (phase === "transcribing") {
					this.voiceHint("busy");
					return false;
				}
				if (phase === "feedback") return this.resumeVoiceUi();
				const start = findVoiceButton("start");
				if (start) {
					if (start.disabled) {
						this.voiceHint("locked");
						return false;
					}
					this.voiceUi = "ui";
					start.click?.();
					this.voiceState = "recording";
					this.notify();
					this.watchVoiceUi();
					window.dispatchEvent(new CustomEvent("dsh-micro:voice", { detail: { type: "push-to-talk-start" } }));
					return true;
				}
				// 模型没准备好时官方按钮会变成"打开语音输入引导"：点它等于用户点按钮。
				const setup = findVoiceButton("setup");
				if (setup) {
					setup.click?.();
					this.voiceHint("notReady");
					return false;
				}
				this.voiceHint(this.speechService() ? "uiMissing" : "missing");
				return false;
			}

			/** 上一次录音停在提示行：直接续接下一段（优先"重新录音"，否则关掉提示再开始）。 */
			resumeVoiceUi() {
				const retry = findVoiceButton("retry");
				if (retry && !retry.disabled) {
					this.voiceLastPhase = "feedback";
					this.voiceUi = "ui";
					retry.click?.();
					this.voiceState = "recording";
					this.notify();
					this.watchVoiceUi();
					return true;
				}
				// 只有"取消"时：先关掉提示，下一帧再点开始（按钮是重新渲染出来的）。
				const cancel = findVoiceDismissButton();
				if (cancel) cancel.click?.();
				this.voiceUi = "ui";
				this.voiceLastPhase = "feedback";
				setTimeout(() => {
					if (this.voiceUi !== "ui" || !this.ptt?.down) {
						this.voiceUi = null;
						return;
					}
					const start = findVoiceButton("start");
					if (!start || start.disabled) {
						this.voiceUi = null;
						this.voiceHint("uiMissing");
						return;
					}
					start.click?.();
					this.voiceState = "recording";
					this.notify();
					this.watchVoiceUi();
				}, 80);
				return true;
			}

			/** 松开：点官方"停止并识别"；还在等权限时点取消。 */
			voiceStop(reason) {
				window.dispatchEvent(new CustomEvent("dsh-micro:voice", { detail: { type: "push-to-talk-stop", reason } }));
				if (this.voiceUi !== "ui") return;
				this.voiceUi = null;
				const stop = findVoiceButton("stop");
				if (stop && !stop.disabled) {
					stop.click?.();
					this.voiceState = "processing";
					this.notify();
					this.watchVoiceUi("stop");
					return;
				}
				const cancel = findVoiceDismissButton();
				if (cancel) cancel.click?.();
				this.voiceState = "idle";
				this.notify();
			}

			// ---- 动作分发 ---------------------------------------------------
			async dispatch(action, context = {}) {
				const parsed = parseAction(action);
				try {
					switch (parsed.type) {
						case "noop":
							return;
						case "text":
							if (!insertIntoComposer(parsed.value)) toast(t("toast.noComposer"), "warn");
							return;
						case "url":
							if (parsed.value) window.open(parsed.value, "_blank", "noopener,noreferrer");
							return;
						case "skill": {
							const mention = `$${parsed.value} `;
							if (!insertIntoComposer(mention)) toast(t("toast.noComposer"), "warn");
							return;
						}
						case "ptt":
							// 由按键路径直接驱动状态机，这里只处理误用。
							this.onPttPress();
							return;
						case "command":
							await this.executeCommand(parsed.value, context);
							return;
						default:
							await this.runVerb(parsed.value, parsed.arg, context);
					}
				} catch (error) {
					this.log(t("log.actionFailed", { "action": actionLabel(action), "error": error?.message ?? error }));
					toast(t("toast.actionFailed", { "action": actionLabel(action) }), "error");
				}
			}

			/** 原版命令 id 的本地实现；没有实现的交给宿主的命令注册表。 */
			async executeCommand(command, context) {
				const ctx = this.ctx;
				switch (command) {
					case "session.new":
					case "newTask": {
						const workspace = service(ctx, "uiWorkspace");
						if (workspace?.startSession) workspace.startSession();
						else toast(t("toast.noNewChat"), "warn");
						return;
					}
					case "session.fork":
					case "forkThread": {
						const current = this.currentSessionId();
						if (current) await sessionsOf(ctx)?.fork?.({ sessionId: current, increaseTitle: true });
						return;
					}
					case "approval.approve":
						return this.answerApproval("allowed-once");
					case "approval.decline":
						return this.answerApproval("rejected");
					case "composer.submit":
						if (!submitComposer()) toast(t("toast.noSubmit"), "warn");
						return;
					case "composer.addFiles": {
						const input = document.querySelector('input[type="file"]');
						if (input) input.click();
						else toast(t("toast.noFilePicker"), "warn");
						return;
					}
					case "composer.addPhotos": {
						const input =
							document.querySelector('input[type="file"][accept*="image"]') ??
							document.querySelector('input[type="file"]');
						if (input) input.click();
						else toast(t("toast.noPhotoPicker"), "warn");
						return;
					}
					case "composer.toggleFastMode":
						if (!this.toggleFastMode()) toast(t("toast.noFastMode"), "warn");
						return;
					case "settings":
						return this.openPanel();
					case "openBrowserTab":
						window.open("about:blank", "_blank", "noopener");
						return;
					case "toggleTerminal":
					case "toggleReviewTab":
					case "openSideChat":
					case "manageTasks":
					case "openSkills":
					case "openFolder":
					case "copyConversationMarkdown":
					case "archiveThread":
					case "toggleThreadPin":
					case "environmentAction1":
					case "feedback":
					default:
						await this.forwardCommand(command, context);
				}
			}

			/** 交给宿主命令注册表：认识就执行，不认识就明确告诉用户。 */
			async forwardCommand(command, context) {
				const ctx = this.ctx;
				const current = context.sessionId ?? this.currentSessionId();
				const commands = service(ctx, "remote.commands");
				const slash = `/${String(command).replace(/^\/+/, "")}`;
				try {
					if (current && commands?.execute) {
						const result = await commands.execute(current, slash);
						if (result !== false) return;
					}
				} catch {
					/* fall through to the toast */
				}
				this.log(t("log.commandUnavailable", { "command": command }));
				toast(t("toast.commandUnavailable", { "command": command }), "warn");
			}

			/**
			 * Bring the plugin's own panel forward.
			 *
			 * The panel is a main-column page selected by the sidebar row, so the
			 * layout service is the honest entry point: it checks the live `main`
			 * registry and leaves the current panel alone when the seat is not
			 * mounted. The old `dsh:open-settings` event is gone with the settings
			 * section it named — no host ever listened for it, so the knob's long
			 * press used to end in nothing.
			 */
			openPanel() {
				const layout = service(this.ctx, "layout");
				try {
					if (layout && typeof layout.selectPanel === "function") {
						layout.selectPanel(PANEL_ID);
						return true;
					}
				} catch (error) {
					// An absent main occupant throws without changing the selection.
				}
				toast(t("toast.noPanel"), "warn");
				return false;
			}

			toggleFastMode() {
				const current = this.currentSessionId();
				const directories = service(this.ctx, "modelDirectories");
				const directory = directories?.directoryFor?.(current);
				const snapshot = directory?.getSnapshot?.();
				const selection = snapshot?.current ?? snapshot?.selection;
				if (!directory?.select || !selection) return false;
				const fast = selection.fastMode ?? selection.fast ?? false;
				if (typeof directory.setFastMode === "function") {
					directory.setFastMode(!fast);
					return true;
				}
				if ("fastMode" in selection) {
					void directory.select({ ...selection, fastMode: !fast });
					return true;
				}
				return false;
			}

			/** 0.2.x 的私有动词，保持可用以免旧配置失效。 */
			async runVerb(verb, arg, context) {
				const ctx = this.ctx;
				const current = this.currentSessionId();
				switch (verb) {
					case "session.open": {
						const slot = Number(arg);
						const assigned = Array.isArray(this.agentSlots) ? this.agentSlots[slot] : null;
						if (assigned) return openSession(ctx, assigned);
						const entries = mainSessionEntries(sessionsOf(ctx)?.list, this.subagentIds);
						const entry = entries[slot];
						if (entry) openSession(ctx, entry.id);
						return;
					}
					case "session.prev":
					case "session.next": {
						const entries = mainSessionEntries(sessionsOf(ctx)?.list, this.subagentIds);
						if (entries.length === 0) return;
						const index = Math.max(0, entries.findIndex((entry) => entry.id === current));
						const next =
							verb === "session.next"
								? (index + 1) % entries.length
								: (index - 1 + entries.length) % entries.length;
						return openSession(ctx, entries[next].id);
					}
					case "session.new":
						return this.executeCommand("session.new");
					case "session.fork":
						return this.executeCommand("session.fork");
					case "plan.toggle": {
						const commands = service(ctx, "remote.commands");
						if (current && commands?.execute) await commands.execute(current, "/plan");
						else toast(t("toast.noPlanMode"), "warn");
						return;
					}
					case "effort.up":
					case "effort.down":
						await this.stepEffort(current, verb === "effort.up" ? 1 : -1);
						return;
					case "approval.allow":
						return this.answerApproval("allowed-once");
					case "approval.reject":
						return this.answerApproval("rejected");
					case "settings.open":
						return this.openPanel();
					case "knob.select":
						synthesizeKey("Enter", "Enter");
						return;
					case "knob.bottom":
						window.scrollTo({ top: document.body.scrollHeight, behavior: "smooth" });
						return;
					default:
						return this.forwardCommand(verb, context);
				}
			}

			currentSessionId() {
				const ctx = this.ctx;
				const uiSession = service(ctx, "uiSession");
				const sessions = sessionsOf(ctx) ?? {};
				const candidates = [
					sessions.activeId,
					sessions.current,
					(typeof sessions.list?.getSnapshot === "function" ? sessions.list.getSnapshot() : undefined),
					uiSession?.sessionId,
					uiSession?.id,
				];
				for (const candidate of candidates) {
					if (typeof candidate === "string") return candidate;
					if (candidate && typeof candidate.getSnapshot === "function") {
						const value = candidate.getSnapshot();
						if (typeof value === "string") return value;
						if (value && typeof value === "object") {
							const id = value.id ?? value.sessionId;
							if (typeof id === "string") return id;
						}
					}
				}
				const entries = mainSessionEntries(sessionsOf(ctx)?.list, this.subagentIds);
				return entries[0]?.id ?? null;
			}

			/** Load the DSH skill catalog for the current session (reference: 技能 group). */
			loadSkills() {
				try {
					const skills = service(this.ctx, "remote.skills") ?? service(this.ctx, "remote.skills.list");
					const sessionId = this.currentSessionId();
					if (!skills || typeof skills.list !== "function" || !sessionId) {
						this.skills = [];
						this.notify();
						return;
					}
					if (this.skillsLoadedFor === sessionId) return;
					this.skillsLoadedFor = sessionId;
					Promise.resolve()
						.then(() => skills.list({ sessionId }))
						.then((result) => {
							if (!result || result.ok === false) {
								this.skills = [];
								this.notify();
								return;
							}
							const payload = result.value ?? result.data ?? result.result ?? result.skills ?? result.items ?? [];
							const rows = Array.isArray(payload) ? payload : payload?.skills ?? payload?.items ?? [];
							this.skills = rows
								.map((entry) => {
									const name = entry?.name ?? entry?.id;
									if (!name) return null;
									return {
										id: `skill:${name}`,
										label: String(name),
										desc: entry.description ?? entry.summary ?? "",
										kind: t("agent.types.skill"),
									};
								})
								.filter(Boolean);
							this.notify();
						})
						.catch(() => {
							this.skills = [];
							this.notify();
						});
				} catch {
					this.skills = [];
					this.notify();
				}
			}

			async stepEffort(sessionId, delta) {
				if (!sessionId) return;
				const directories = service(this.ctx, "modelDirectories");
				const directory = directories?.directoryFor?.(sessionId);
				const snapshot = directory?.getSnapshot?.() ?? directory?.catalog?.getSnapshot?.();
				const current = snapshot?.current ?? snapshot?.selection;
				const efforts = snapshot?.reasoning?.efforts ?? snapshot?.catalog?.reasoning?.efforts ?? [];
				if (!current || efforts.length === 0) {
					this.log(t("log.effortEnum"));
					return;
				}
				const index = efforts.findIndex((effort) => effort.id === current.reasoningEffort);
				const next = efforts[(index + delta + efforts.length) % efforts.length];
				await directory.select({ provider: current.provider, model: current.model, reasoningEffort: next.id });
				this.log(`effort → ${next.id}`);
			}

			// ---- approvals ---------------------------------------------------
			registerApproval() {
				const remote = service(this.ctx, "remote");
				if (!remote || typeof remote.$on !== "function") return;
				this.ctx.effect(
					() =>
						remote.$on("approval/request", (request, next) => {
							const downstream = next();
							return Promise.race([downstream, this.waitForApproval(request)]).finally(() => {
								if (this.pendingApproval?.request === request) this.pendingApproval = null;
								this.scheduleLighting();
							});
						}),
					"dsh-micro: approval answerer",
				);
			}

			waitForApproval(request) {
				return new Promise((resolve) => {
					this.pendingApproval = { request, resolve, sessionId: request?.sessionId };
					this.log(t("log.approvalPending"));
					this.scheduleLighting();
				});
			}

			async answerApproval(outcome) {
				const pending = this.pendingApproval;
				if (!pending) {
					this.log(t("log.noApprovals"));
					toast(t("log.noApprovals"), "warn");
					return;
				}
				this.pendingApproval = null;
				pending.resolve(outcome);
				this.log(outcome === "allowed-once" ? t("log.approvedHw") : t("log.rejectedHw"));
				this.scheduleLighting();
			}

			// ---- lighting ----------------------------------------------------
			// 合成在宿主半（`lib/index.js` 的 `SessionLighting`，按原版 §4.6 算法：
			// 选中/未读呼吸、其余常亮、氛围灯只在选中 working / 4 s 选中窗口 / 语音态
			// 亮）。渲染端只上报宿主看不见的 UI 态——当前选中会话、未读、待审批、语音。
			// 以前渲染端自己算整份模型，但它的会话投影在面板打开前是空的，会推一份
			// 「全灭」把键盘压黑；现在只有提示跨边界，模型只有一个所有者。
			scheduleLighting() {
				if (this.disposed || this.lightingTimer) return;
				this.lightingTimer = setTimeout(() => {
					this.lightingTimer = null;
					void this.pushLightHints();
				}, 50);
				this.lightingTimer.unref?.();
			}

			/**
			 * 立刻上报一次提示。切会话必须走这条路：原版主进程在选中槽位变化的
			 * 那一帧就重开 4 s 选中高亮窗口（`.ref/notes/switch-animation.md`），
			 * 而这里只能由渲染端上报，等 1.5 s 轮询再亮就已经切完了。
			 *
			 * 打开会话后会话 store 未必同帧更新，所以补两次延迟复核；`pushLightHints`
			 * 按内容去重，多推一次没有代价。
			 */
			flushLighting() {
				if (this.disposed) return;
				if (this.lightingTimer) {
					clearTimeout(this.lightingTimer);
					this.lightingTimer = null;
				}
				void this.pushLightHints();
				for (const delay of [120, 400]) {
					const timer = setTimeout(() => {
						void this.pushLightHints();
					}, delay);
					timer.unref?.();
				}
			}

			/**
			 * 订阅会话选中态（拿得到 observable 就订阅，拿不到就只剩轮询）。
			 * 用户在侧栏点会话不会经过我们的按键分发，订阅是唯一能立刻看到它的路。
			 */
			watchSelection() {
				const sessions = sessionsOf(this.ctx);
				const candidates = [service(this.ctx, "uiSession"), sessions?.list, sessions?.active, sessions?.current];
				for (const candidate of candidates) {
					if (!candidate || typeof candidate.subscribe !== "function") continue;
					try {
						const dispose = candidate.subscribe(() => this.scheduleLighting());
						if (typeof dispose !== "function") continue;
						this.selectionDispose = dispose;
						return true;
					} catch {
						/* 下一个候选 */
					}
				}
				return false;
			}

			startLightingLoop() {
				if (this.lightingInterval) return;
				// 诊断：每 5 s 把 owner / 收到的按键数报到宿主，键没反应时一眼看出
				// 是"HID 没到"还是"本窗口不是主控"。
				this.beaconInterval = setInterval(() => reportClient(), 5000);
				this.beaconInterval.unref?.();
				// 宿主自己也每 1.5 s 复核一次；这里只在 UI 状态变化时推提示。
				this.lightingInterval = setInterval(() => this.scheduleLighting(), 1500);
				this.lightingInterval.unref?.();
				try {
					this.watchSelection();
				} catch {
					/* 订阅是加速路径：拿不到还有轮询兜底 */
				}
				this.scheduleLighting();
			}

			/** 宿主看不到的灯光状态：选中会话、未读/待审批、语音态。 */
			lightHints() {
				const current = this.currentSessionId();
				const waiting = this.pendingApproval?.sessionId ?? null;
				const entries = mainSessionEntries(sessionsOf(this.ctx)?.list, this.subagentIds);
				const statuses = {};
				for (const entry of entries) {
					const status = sessionStatus(entry, { current, waiting });
					if (status === "unread" || status === "awaiting-approval" || status === "awaiting-response") {
						statuses[entry.id] = status;
					}
				}
				if (waiting) statuses[waiting] = "awaiting-approval";
				// 语音态：采集=recording（海绿蛇形）→ 转写=processing（白色蛇形）→
				// 完成=completed（白色常亮 1.5 s），与原版 voiceState 语义一致。
				// 官方听写按钮自己在跑（用户点按钮触发）时，直接读它的 data-voice-activity，
				// 让设备灯光和界面上的录音状态一致。
				const uiPhase = voiceUiActivity()?.getAttribute?.("data-voice-activity") ?? "";
				const pttActive = ["pressed", "waiting", "latched"].includes(this.ptt?.state);
				const voiceState = uiPhase
					? voicePhaseState(uiPhase)
					: this.voiceState === "processing" || this.voiceState === "completed"
						? this.voiceState
						: pttActive || this.voiceState === "recording"
							? "recording"
							: "idle";
				return {
					selected: current ?? null,
					voiceState,
					statuses,
				};
			}

			async pushLightHints() {
				if (this.disposed) return;
				const hints = this.lightHints();
				const key = JSON.stringify(hints);
				if (key === this.lastHintKey) return;
				this.lastHintKey = key;
				try {
					await post({ op: "light-hints", hints });
				} catch {
					this.lastHintKey = "";
				}
			}

			// ---- joystick ----------------------------------------------------
			onStick(params) {
				const distance = Number(params.d ?? 0);
				const angle = Number(params.a ?? 0);
				if (distance < STICK_DEADZONE) {
					this.lastStick = 0;
					return;
				}
				if (distance < STICK_TRIGGER) return;
				const direction = directionOf(angle);
				if (direction === 0 || direction === this.lastStick) return;
				this.lastStick = direction;
				const name = { 1: "STICK_UP", 2: "STICK_RIGHT", 3: "STICK_DOWN", 4: "STICK_LEFT" }[direction];
				const action = this.resolveSlot(name);
				if (action === "noop" || !this.owner) return;
				this.log(t("log.stickMove", { "name": name, "action": actionLabel(action) }));
				// 原版在有输入区时延迟 220 ms，避免扫过方向时误触发。
				const delay = document.activeElement && document.activeElement.isContentEditable ? 220 : 0;
				const fire = () => void this.dispatch(action, { key: name });
				if (delay > 0) {
					const timer = setTimeout(fire, delay);
					timer.unref?.();
				} else {
					fire();
				}
			}
		}

		/** 会话状态推导：优先用宿主给的字段，缺失时按当前/审批回退。 */
		function sessionStatus(entry, { current, waiting }) {
			if (!entry) return "off";
			if (waiting && entry.id === waiting) return "awaiting-approval";
			const raw = String(entry.status ?? entry.state ?? "").toLowerCase();
			if (raw === "working" || raw === "running" || raw === "streaming" || entry.working === true) return "working";
			if (raw === "error" || raw === "failed" || entry.error === true) return "error";
			if (raw === "awaiting-response" || raw === "awaiting_response" || entry.attention === true) return "awaiting-response";
			if (entry.unread === true || entry.hasUnread === true) return "unread";
			if (entry.id === current) return "idle";
			return "idle";
		}

		/**
		 * 1=up 2=right 3=down 4=left; 0 inside the deadzone.
		 *
		 * Sector boundaries from the reference (`pU`, original-runtime.md §4.1):
		 * angle 0 is +x (right) and grows clockwise, so
		 *   right [0, .125) ∪ [.875, 1)   down [.125, .375)
		 *   left  [.375, .625)            up   [.625, .875)
		 * The previous version had up and down swapped, which is why pushing up ran
		 * `session.new` and pulling down toggled plan mode.
		 */
		function directionOf(angle) {
			const a = ((angle % 1) + 1) % 1;
			if (a < 0.125 || a >= 0.875) return 2;
			if (a < 0.375) return 3;
			if (a < 0.625) return 4;
			return 1;
		}

		function openSession(ctx, sessionId) {
			const workspace = service(ctx, "uiWorkspace");
			if (workspace?.openSession) workspace.openSession(sessionId);
			else sessionsOf(ctx)?.retain?.(sessionId, { source: "mainView" });
			// 原版在选中槽位变化的那一帧就重开 4 s 选中高亮窗口；渲染端只能上报，
			// 所以「切会话」这个动作本身要立刻补一次提示（见 flushLighting）。
			controller?.flushLighting?.();
		}

		let controller = null;

		// ------------------------------------------------------------ controls
		function PanelRow({ title, description, children }) {
			return jsx("div", {
				className: "cm-row",
				children: [
					jsx("div", {
						className: "cm-row-main",
						children: [
							jsx("div", { className: "cm-row-title", children: title }, "t"),
							description ? jsx("div", { className: "cm-row-desc", children: description }, "d") : null,
						],
					}, "main"),
					jsx("div", { className: "cm-row-control", children }, "control"),
				],
			});
		}

		/** 亮度滑块：0..100，步长 10（与原版一致）。 */
		function Slider({ value, onChange, ariaLabel, step = 10, min = 0, max = 100 }) {
			return jsx("input", {
				className: "cm-slider",
				type: "range",
				min,
				max,
				step,
				value: Math.round(Number(value) || 0),
				"aria-label": ariaLabel,
				onChange: (event) => onChange(Number(event.target.value)),
			});
		}

		function Select({ value, options, onChange, ariaLabel }) {
			return jsx("select", {
				className: "cm-select",
				value,
				"aria-label": ariaLabel,
				onChange: (event) => onChange(event.target.value),
				children: options.map((option) => jsx("option", { value: option.value, children: option.label }, option.value)),
			});
		}

		function Toggle({ value, onChange, ariaLabel }) {
			return jsx("button", {
				type: "button",
				className: "cm-toggle",
				"data-on": value ? "true" : "false",
				"aria-label": ariaLabel,
				"aria-pressed": value,
				onClick: () => onChange(!value),
				children: jsx("span", {}),
			});
		}

