		/** Render one extracted SVG node exactly as the reference bundle defines it. */
		function iconNode(node, key) {
			// The key is jsx()'s third argument, never a prop: spreading it in
			// makes React warn once per icon path node.
			const props = Object.assign({}, node.attrs);
			if (node.children && node.children.length > 0) {
				props.children = node.children.map((child, index) => iconNode(child, `${key}-${index}`));
			}
			return jsx(node.tag, props, key);
		}

		/** Keycap ids rendered on the physical keycaps (SPLIT -> FORK, BRCH -> DRAFT). */
