		class Boundary extends React.Component {
			constructor(props) {
				super(props);
				this.state = { error: null };
			}
			static getDerivedStateFromError(error) {
				return { error };
			}
			render() {
				if (this.state.error) {
					return jsx("pre", {
						style: { color: "#c0392b", whiteSpace: "pre-wrap", font: "11px/1.5 ui-monospace, monospace" },
						children: t("diag.crash", { stack: this.state.error?.stack ?? String(this.state.error) }),
					});
				}
				return this.props.children;
			}
		}

